export class AlertEventKeys {
  constructor() {
    this.occurrences = new Map();
  }

  next(type, scope, authority) {
    const series = `${type}:${scope}`,
      occurrence = (this.occurrences.get(series) || 0) + 1;
    this.occurrences.set(series, occurrence);
    const authoritative = authority == null ? "local" : String(authority);
    return `${series}:${authoritative}:${occurrence}`;
  }
}

export function operationalAlerts(before, state, myId, keys) {
  if (!before) return [];
  const me = state.players.find((player) => player.id === myId),
    oldMe = before.players.find((player) => player.id === myId);
  if (!me || !oldMe) return [];
  const alerts = [],
    oldRegions = new Map(before.regions.map((region) => [region.id, region]));
  const add = (text, type, scope, authority) =>
    alerts.push({ text, key: keys.next(type, scope, authority) });

  for (const region of state.regions) {
    const old = oldRegions.get(region.id),
      foreign = Object.keys(region.campaigns || {}).filter((id) => id !== myId),
      oldForeign = Object.keys(old?.campaigns || {}).filter(
        (id) => id !== myId,
      );
    if (region.ownerId === myId && foreign.length && oldForeign.length === 0)
      add(
        `New supply contest at ${region.name}.`,
        "contest",
        region.id,
        state.elapsed,
      );
    if (old?.ownerId === myId && region.ownerId !== myId)
      add(
        `${region.name} contract changed supplier.`,
        "loss",
        region.id,
        old.acquiredAt,
      );
    if (region.ownerId === myId && region.overCapacity && !old?.overCapacity)
      add(
        `${region.name} is over capacity; production and arrivals are paused.`,
        "capacity",
        region.id,
        state.elapsed,
      );
    if (
      region.ownerId === myId &&
      old?.programme?.pending &&
      region.programme &&
      !region.programme.pending
    )
      add(
        `${region.name} continuity programme is active.`,
        "programme-active",
        region.id,
        region.programme.startedAt,
      );
    if (region.ownerId === myId && old?.programme && !region.programme)
      add(
        `${region.name} continuity programme ended.`,
        "programme-end",
        region.id,
        old.programme.startedAt,
      );
  }
  if (me.unusedManufacturing > 0 && oldMe.unusedManufacturing <= 0)
    add(
      "Manufacturing funding is unused; review factory capacity and product eligibility.",
      "unused",
      myId,
      state.elapsed,
    );
  const blocked = me.manufacturingFunding > 0 && me.manufacturingSpend <= 0,
    oldBlocked =
      oldMe.manufacturingFunding > 0 && oldMe.manufacturingSpend <= 0;
  if (blocked && !oldBlocked)
    add(
      "Production is blocked; review capacity, levels, and selected treatment.",
      "blocked",
      myId,
      state.elapsed,
    );
  if (me.dominance.holding && !oldMe.dominance?.holding)
    add(
      `Dominance hold started: ${me.dominance.regions}/${me.dominance.threshold} regions.`,
      "dominance",
      myId,
      state.elapsed,
    );
  return alerts;
}
